const items = $input.all();

const strongAiPatterns = [
  /\bopenai\b/i,
  /\bchatgpt\b/i,
  /\banthropic\b/i,
  /\bclaude\b/i,
  /\bgemini\b/i,
  /\bcopilot\b/i,
  /\bllm\b/i,
  /\bllms\b/i,
  /\bgenerative ai\b/i,
  /\bartificial intelligence\b/i,
  /\bmachine learning\b/i,
  /\bai agent\b/i,
  /\bai agents\b/i,
  /\bagentic\b/i,
  /\bagentic workflows\b/i,
  /\bnvidia\b/i,
  /\bai chip\b/i,
  /\bai chips\b/i,
  /\bfoundation model\b/i
];

const weakAiPatterns = [
  /\bai\b/i,
  /\bautomation\b/i,
  /\brobot\b/i,
  /\bneural\b/i
];

const businessPatterns = [
  /\benterprise\b/i,
  /\bbusiness\b/i,
  /\bworkflow\b/i,
  /\bworkflows\b/i,
  /\bproductivity\b/i,
  /\bcompliance\b/i,
  /\bgovernance\b/i,
  /\bregulation\b/i,
  /\bsecurity\b/i,
  /\bsafety\b/i,
  /\bdeveloper\b/i,
  /\bdevelopers\b/i,
  /\bstartup\b/i,
  /\bfunding\b/i,
  /\binvestment\b/i,
  /\bchips\b/i,
  /\bchip\b/i,
  /\bcloud\b/i,
  /\bapi\b/i,
  /\bautomation\b/i,
  /\btool\b/i,
  /\btools\b/i,
  /\bplatform\b/i,
  /\blaunch\b/i,
  /\benterprise ai\b/i,
  /\binfrastructure\b/i
];

const excludePatterns = [
  /\bairpods\b/i,
  /\blawn mower\b/i,
  /\bmovie\b/i,
  /\btrailer\b/i,
  /\bgaming\b/i,
  /\bgame\b/i,
  /\bconsole\b/i,
  /\bplaystation\b/i,
  /\bps5\b/i,
  /\bnintendo\b/i,
  /\bswitch\b/i,
  /\btv show\b/i,
  /\bcelebrity\b/i,
  /\bsports\b/i,
  /\bcamera bag\b/i,
  /\bbackpack\b/i,
  /\bsale\b/i,
  /\bdiscount\b/i
];

const htmlEntities = {
  '&amp;': '&',
  '&quot;': '"',
  '&apos;': "'",
  '&#39;': "'",
  '&nbsp;': ' ',
  '&rsquo;': '’',
  '&lsquo;': '‘',
  '&rdquo;': '”',
  '&ldquo;': '“',
  '&ndash;': '–',
  '&mdash;': '—',
  '&euro;': '€',
  '&yen;': '¥'
};

function decodeHtmlEntities(value) {
  return String(value || '')
    .replace(/&#(\d+);/g, (_, code) => String.fromCharCode(Number(code)))
    .replace(/&#x([0-9a-f]+);/gi, (_, code) => String.fromCharCode(parseInt(code, 16)))
    .replace(/&[a-zA-Z0-9#]+;/g, (entity) => htmlEntities[entity] || entity);
}

function cleanText(value) {
  return decodeHtmlEntities(value)
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]*>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function slugify(value) {
  return cleanText(value)
    .toLowerCase()
    .replace(/https?:\/\//g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 80);
}

function getText(item) {
  return [
    item.json.title,
    item.json.contentSnippet,
    item.json.summary,
    item.json.content,
    item.json.link
  ]
    .filter(Boolean)
    .map(cleanText)
    .join(' ');
}

function hasMatch(patterns, text) {
  return patterns.some((pattern) => pattern.test(text));
}

function isRelevant(item) {
  const text = getText(item);
  const title = cleanText(item.json.title || '');

  const hasStrongAi = hasMatch(strongAiPatterns, text);
  const hasWeakAi = hasMatch(weakAiPatterns, text);
  const hasBusinessContext = hasMatch(businessPatterns, text);
  const hasExcludedTopic = hasMatch(excludePatterns, text);

  if (hasExcludedTopic && !hasStrongAi) {
    return false;
  }

  if (hasStrongAi) {
    return true;
  }

  if (hasWeakAi && hasBusinessContext) {
    return true;
  }

  return false;
}

function getCategory(text) {
  const lower = text.toLowerCase();

  if (
    lower.includes('compliance') ||
    lower.includes('regulation') ||
    lower.includes('governance') ||
    lower.includes('safety') ||
    lower.includes('security') ||
    lower.includes('board') ||
    lower.includes('lawsuit') ||
    lower.includes('trial')
  ) {
    return 'AI Governance';
  }

  if (
    lower.includes('agent') ||
    lower.includes('agentic') ||
    lower.includes('workflow') ||
    lower.includes('automation')
  ) {
    return 'AI Workflows';
  }

  if (
    lower.includes('chip') ||
    lower.includes('chips') ||
    lower.includes('nvidia') ||
    lower.includes('infrastructure') ||
    lower.includes('cloud') ||
    lower.includes('data center') ||
    lower.includes('datacenter')
  ) {
    return 'AI Infrastructure';
  }

  if (
    lower.includes('developer') ||
    lower.includes('api') ||
    lower.includes('tool') ||
    lower.includes('tools') ||
    lower.includes('platform')
  ) {
    return 'AI Tools';
  }

  return 'AI News';
}

function getScore(text) {
  const lower = text.toLowerCase();
  let score = 60;

  if (lower.includes('openai') || lower.includes('chatgpt')) score += 18;
  if (lower.includes('anthropic') || lower.includes('claude')) score += 16;
  if (lower.includes('gemini') || lower.includes('copilot')) score += 14;

  if (
    lower.includes('agent') ||
    lower.includes('agentic') ||
    lower.includes('workflow') ||
    lower.includes('automation')
  ) {
    score += 12;
  }

  if (
    lower.includes('enterprise') ||
    lower.includes('business') ||
    lower.includes('productivity') ||
    lower.includes('company') ||
    lower.includes('companies')
  ) {
    score += 10;
  }

  if (
    lower.includes('compliance') ||
    lower.includes('regulation') ||
    lower.includes('governance') ||
    lower.includes('security') ||
    lower.includes('safety') ||
    lower.includes('board') ||
    lower.includes('lawsuit') ||
    lower.includes('trial')
  ) {
    score += 10;
  }

  if (
    lower.includes('nvidia') ||
    lower.includes('chip') ||
    lower.includes('chips') ||
    lower.includes('infrastructure') ||
    lower.includes('cloud') ||
    lower.includes('data center') ||
    lower.includes('datacenter')
  ) {
    score += 10;
  }

  if (
    lower.includes('funding') ||
    lower.includes('investment') ||
    lower.includes('invest') ||
    lower.includes('launch') ||
    lower.includes('production')
  ) {
    score += 6;
  }

  if (hasMatch(excludePatterns, text)) {
    score -= 18;
  }

  return Math.max(45, Math.min(score, 96));
}

function getRecommendation(score, category) {
  if (score >= 80) {
    return `Für das Trend-Radar priorisieren und kurzfristig prüfen, ob daraus ein konkreter Use Case im Bereich ${category} entsteht.`;
  }

  if (score >= 70) {
    return `Beobachten und mit weiteren Quellen abgleichen, ob sich das Signal im Bereich ${category} verstärkt.`;
  }

  return `Nur als schwaches Signal beobachten und erst priorisieren, wenn weitere relevante Quellen das Thema bestätigen.`;
}

function getBusinessImpact(category, title) {
  if (category === 'AI Governance') {
    return `Dieses Signal ist für AI Governance relevant, weil es auf Veränderungen bei Führung, Kontrolle, Regulierung, Sicherheit oder Vertrauen im KI-Markt hinweist: ${title}`;
  }

  if (category === 'AI Infrastructure') {
    return `Dieses Signal ist für AI Infrastructure relevant, weil es auf neue Investitionen, Chip-Kapazitäten, Rechenleistung oder technische Grundlagen für KI-Systeme hinweist: ${title}`;
  }

  if (category === 'AI Workflows') {
    return `Dieses Signal ist für AI Workflows relevant, weil es auf neue Automatisierungsmöglichkeiten, Agenten-Systeme oder produktivere KI-Prozessketten hinweist: ${title}`;
  }

  if (category === 'AI Tools') {
    return `Dieses Signal ist für AI Tools relevant, weil es auf neue Plattformen, APIs, Entwicklerwerkzeuge oder produktnahe KI-Anwendungen hinweist: ${title}`;
  }

  return `Dieses Signal ist für die KI-Marktbeobachtung relevant, weil es auf mögliche Veränderungen bei KI-Unternehmen, Produkten, Infrastruktur oder Marktstrategien hinweist: ${title}`;
}

const relevantItems = items.filter(isRelevant);

return relevantItems.map((item) => {
  const title = cleanText(item.json.title || 'Unbenannter RSS-Trend');
  const link = item.json.link || '';
  const pubDate = item.json.pubDate || item.json.isoDate || '';
  const text = getText(item);

  const cleanSummary = cleanText(
    item.json.contentSnippet ||
    item.json.summary ||
    item.json.content ||
    title
  );

  const score = getScore(text);
  const category = getCategory(text);
  const status = score >= 80 ? 'Hohe Relevanz' : 'Beobachten';

  return {
    json: {
      id: slugify(link || title),
      name: title,
      category,
      status,
      score,
      businessImpact: getBusinessImpact(category, title),
      summary: cleanSummary.slice(0, 350),
      recommendation: getRecommendation(score, category),
      source: 'The Verge RSS',
      timeframe: pubDate ? 'RSS Import' : 'Unbekannt',
      signalType: 'RSS'
    }
  };
});

const items = $input.all();

function cleanText(value) {
  if (value === null || value === undefined) return "";

  return String(value)
    .replace(/<[^>]*>/g, " ")
    .replace(/&amp;/g, "&")
    .replace(/&quot;/g, "\"")
    .replace(/&#39;/g, "'")
    .replace(/&apos;/g, "'")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/\s+/g, " ")
    .trim();
}

function cleanNumber(value, fallback = 0) {
  const number = Number(value);
  if (Number.isFinite(number)) return number;
  return fallback;
}

function normalizeScore(value) {
  return Math.max(0, Math.min(100, cleanNumber(value, 0)));
}

function normalizeId(value) {
  const cleaned = cleanText(value);

  if (!cleaned) return "";

  return cleaned
    .toLowerCase()
    .replace(/_/g, "-")
    .replace(/[^a-z0-9-]/g, "-")
    .replace(/-+/g, "-")
    .replace(/^-|-$/g, "")
    .slice(0, 80);
}

const output = [];

for (const item of items) {
  const input = item.json || {};

  const normalized = {
    id: normalizeId(input.id || input.name),
    name: cleanText(input.name || "Unbenannter Trend"),
    category: cleanText(input.category || "AI News"),
    status: cleanText(input.status || "Neu"),
    score: normalizeScore(input.score),
    businessImpact: cleanText(input.businessImpact || ""),
    summary: cleanText(input.summary || ""),
    recommendation: cleanText(input.recommendation || ""),
    source: cleanText(input.source || ""),
    timeframe: cleanText(input.timeframe || ""),
    signalType: cleanText(input.signalType || ""),

    sourceUrl: cleanText(input.sourceUrl || ""),
    publishedAt: cleanText(input.publishedAt || ""),
    articleTitle: cleanText(input.articleTitle || input.name || ""),
    articleSummary: cleanText(input.articleSummary || input.summary || ""),
    articleBody: cleanText(input.articleBody || input.summary || ""),
    sourceName: cleanText(input.sourceName || input.source || ""),
  };

  if (!normalized.id || !normalized.name) {
    continue;
  }

  output.push({
    json: normalized,
  });
}

return output;

const candidates = $("Trend-Daten normalisieren").all();
const existingRows = $("Bestehende Trends lesen").all();

const existingIds = new Set(
  existingRows
    .map((item) => String(item.json.id || "").trim())
    .filter(Boolean)
);

const newTrends = candidates.filter((item) => {
  const id = String(item.json.id || "").trim();
  return id && !existingIds.has(id);
});

return newTrends;

const items = $input.all();

const SOURCE_CONFIGS = [
  {
    matchNames: ["OpenAI"],
    name: "YouTube – OpenAI",
    quality: 100,
    signalType: "YouTube",
    maxItems: 5,
  },
  {
    matchNames: ["Google DeepMind", "DeepMind"],
    name: "YouTube – Google DeepMind",
    quality: 98,
    signalType: "YouTube",
    maxItems: 5,
  },
  {
    matchNames: ["NVIDIA Developer", "NVIDIA"],
    name: "YouTube – NVIDIA Developer",
    quality: 92,
    signalType: "YouTube",
    maxItems: 5,
  },
  {
    matchNames: ["Everlast AI"],
    name: "YouTube – Everlast AI",
    quality: 82,
    signalType: "YouTube",
    maxItems: 5,
  },
  {
    matchNames: ["Christoph Magnussen"],
    name: "YouTube – Christoph Magnussen",
    quality: 78,
    signalType: "YouTube",
    maxItems: 5,
  },
  {
    matchNames: ["Niklas Steenfatt"],
    name: "YouTube – Niklas Steenfatt",
    quality: 76,
    signalType: "YouTube",
    maxItems: 5,
  },
];

function cleanText(value) {
  if (value === null || value === undefined) return "";

  return String(value)
    .replace(/<[^>]*>/g, " ")
    .replace(/&amp;/g, "&")
    .replace(/&quot;/g, "\"")
    .replace(/&#39;/g, "'")
    .replace(/&apos;/g, "'")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/\s+/g, " ")
    .trim();
}

function normalizeId(value) {
  return cleanText(value)
    .replace(/^yt:video:/i, "")
    .toLowerCase()
    .replace(/_/g, "-")
    .replace(/[^a-z0-9-]/g, "-")
    .replace(/-+/g, "-")
    .replace(/^-|-$/g, "")
    .slice(0, 80);
}

function asArray(value) {
  if (!value) return [];
  return Array.isArray(value) ? value : [value];
}

function getFeedTitle(feed) {
  return cleanText(
    feed?.title ||
    feed?.author?.name ||
    feed?.["media:title"] ||
    ""
  );
}

function getSourceConfig(feed) {
  const feedTitle = getFeedTitle(feed).toLowerCase();
  const authorName = cleanText(feed?.author?.name).toLowerCase();

  const found = SOURCE_CONFIGS.find((config) =>
    config.matchNames.some((name) => {
      const needle = name.toLowerCase();
      return feedTitle.includes(needle) || authorName.includes(needle);
    })
  );

  if (found) return found;

  const fallbackName = getFeedTitle(feed) || "Unknown";

  return {
    matchNames: [fallbackName],
    name: `YouTube – ${fallbackName}`,
    quality: 70,
    signalType: "YouTube",
    maxItems: 5,
  };
}

function getEntryLink(entry, videoId) {
  const link = entry?.link;

  if (typeof link === "string" && link.trim()) {
    return cleanText(link);
  }

  if (link?.href) {
    return cleanText(link.href);
  }

  if (Array.isArray(link)) {
    const alternate = link.find((item) => item?.rel === "alternate" && item?.href);
    if (alternate?.href) return cleanText(alternate.href);

    const firstWithHref = link.find((item) => item?.href);
    if (firstWithHref?.href) return cleanText(firstWithHref.href);
  }

  if (videoId) {
    return `https://www.youtube.com/watch?v=${videoId}`;
  }

  return "";
}

function getVideoId(entry) {
  const directId =
    entry?.["yt:videoId"] ||
    entry?.videoId ||
    entry?.id ||
    "";

  const cleaned = cleanText(directId).replace(/^yt:video:/i, "");

  if (cleaned) return cleaned;

  const url = getEntryLink(entry, "");
  const watchMatch = url.match(/[?&]v=([^&]+)/);
  if (watchMatch?.[1]) return watchMatch[1];

  const shortsMatch = url.match(/\/shorts\/([^/?]+)/);
  if (shortsMatch?.[1]) return shortsMatch[1];

  return "";
}

function getTitle(entry) {
  return cleanText(
    entry?.title ||
    entry?.["media:group"]?.["media:title"] ||
    entry?.["media:title"] ||
    "Unbenanntes YouTube-Signal"
  );
}

function getDescription(entry, title) {
  return cleanText(
    entry?.["media:group"]?.["media:description"] ||
    entry?.["media:description"] ||
    entry?.description ||
    entry?.summary ||
    title
  );
}

function getPublishedAt(entry) {
  return cleanText(
    entry?.published ||
    entry?.pubDate ||
    entry?.isoDate ||
    entry?.updated ||
    ""
  );
}

function getCategory(title, description, sourceConfig) {
  const text = `${title} ${description} ${sourceConfig.name}`.toLowerCase();

  if (
    text.includes("gpu") ||
    text.includes("nvidia") ||
    text.includes("cuda") ||
    text.includes("dgx") ||
    text.includes("jax") ||
    text.includes("kernel") ||
    text.includes("infrastructure") ||
    text.includes("rechenleistung") ||
    text.includes("developer")
  ) {
    return "AI Infrastructure";
  }

  if (
    text.includes("workflow") ||
    text.includes("workflows") ||
    text.includes("agentic") ||
    text.includes("agent") ||
    text.includes("agents") ||
    text.includes("automation") ||
    text.includes("automatisierung") ||
    text.includes("produktivität")
  ) {
    return "AI Workflows";
  }

  if (
    text.includes("research") ||
    text.includes("forschung") ||
    text.includes("benchmark") ||
    text.includes("eval") ||
    text.includes("safety") ||
    text.includes("alignment") ||
    text.includes("model") ||
    text.includes("gpt") ||
    text.includes("claude") ||
    text.includes("gemini") ||
    text.includes("gemma")
  ) {
    return "AI Research";
  }

  if (
    text.includes("demo") ||
    text.includes("introducing") ||
    text.includes("launch") ||
    text.includes("update") ||
    text.includes("app") ||
    text.includes("tool")
  ) {
    return "AI Product Demo";
  }

  return "AI Tools";
}

function getScore(title, description, category, sourceConfig) {
  const text = `${title} ${description}`.toLowerCase();

  let score = sourceConfig.quality || 70;

  if (
    text.includes("agent") ||
    text.includes("agents") ||
    text.includes("agentic") ||
    text.includes("workflow") ||
    text.includes("codex") ||
    text.includes("gpt") ||
    text.includes("claude") ||
    text.includes("gemini") ||
    text.includes("gemma") ||
    text.includes("developer") ||
    text.includes("api")
  ) {
    score += 8;
  }

  if (
    category === "AI Infrastructure" ||
    category === "AI Tools" ||
    category === "AI Workflows"
  ) {
    score += 4;
  }

  return Math.max(1, Math.min(98, Math.round(score)));
}

function getStatus(score) {
  if (score >= 85) return "Hohe Relevanz";
  if (score >= 65) return "Neu";
  return "Beobachten";
}

function getBusinessImpact(category, title) {
  const safeTitle = cleanText(title);

  if (category === "AI Infrastructure") {
    return `Dieses YouTube-Signal ist für AI Infrastructure relevant, weil es auf KI-Infrastruktur, GPUs, Developer-Tools, Rechenleistung oder technische Grundlagen für KI-Systeme hinweist: ${safeTitle}`;
  }

  if (category === "AI Workflows") {
    return `Dieses YouTube-Signal ist für AI Workflows relevant, weil es auf neue Automatisierungs- oder Produktivitätsmöglichkeiten mit KI hinweist: ${safeTitle}`;
  }

  if (category === "AI Research") {
    return `Dieses YouTube-Signal ist für AI Research relevant, weil es Hinweise auf neue Modelle, Forschungsergebnisse, Sicherheitsfragen oder technische Fortschritte liefert: ${safeTitle}`;
  }

  if (category === "AI Product Demo") {
    return `Dieses YouTube-Signal ist für AI Product Demo relevant, weil es offizielle Produktfunktionen, Demos oder neue Anwendungsmöglichkeiten sichtbar macht: ${safeTitle}`;
  }

  return `Dieses YouTube-Signal ist für AI Tools relevant, weil es auf neue Funktionen, Entwicklerwerkzeuge, Agenten oder produktnahe KI-Anwendungen hinweist: ${safeTitle}`;
}

function getRecommendation(score, category) {
  if (score >= 85) {
    return `Für das Trend-Radar priorisieren und prüfen, ob daraus ein konkreter Use Case im Bereich ${category} entsteht.`;
  }

  if (score >= 65) {
    return `Weiter beobachten und prüfen, ob sich daraus ein relevanter Trend im Bereich ${category} entwickelt.`;
  }

  return `Niedrige Priorität. Nur beobachten, falls sich weitere Signale im Bereich ${category} ergeben.`;
}

const output = [];

for (const item of items) {
  const feed = item.json?.feed || item.json;
  const sourceConfig = getSourceConfig(feed);

  const entries = asArray(feed?.entry).slice(0, sourceConfig.maxItems || 5);

  for (const entry of entries) {
    const videoId = getVideoId(entry);
    const id = normalizeId(videoId || entry?.id || entry?.title);

    if (!id) continue;

    const title = getTitle(entry);
    const description = getDescription(entry, title);
    const published = getPublishedAt(entry);
    const sourceUrl = getEntryLink(entry, videoId);
    const category = getCategory(title, description, sourceConfig);
    const score = getScore(title, description, category, sourceConfig);
    const status = getStatus(score);

    output.push({
      json: {
        id,
        name: title,
        category,
        status,
        score,
        businessImpact: getBusinessImpact(category, title),
        summary: (description || title).slice(0, 500),
        recommendation: getRecommendation(score, category),
        source: sourceConfig.name,
        timeframe: published ? "YouTube Upload" : "Unbekannt",
        signalType: sourceConfig.signalType,

        sourceUrl,
        publishedAt: published,
        articleTitle: title,
        articleSummary: (description || title).slice(0, 800),
        articleBody: description || title,
        sourceName: sourceConfig.name,
      },
    });
  }
}

return output;
